int main(){
    int n; cin>>n;
    vector<pair<int,int>> acts(n);
    for(auto&[s,e]:acts) cin>>s>>e;
    sort(acts.begin(),acts.end(),[](auto&a,auto&b){return a.second<b.second;});
    int cnt=0,last=0;
    for(auto&[s,e]:acts) if(s>=last){cnt++;last=e;}
    cout<<cnt<<'\n';
}

